class Solution:
    def sumOfPower(self, nums: list[int]) -> int:
        MOD = 10**9 + 7
        nums.sort()
        ans = 0
        s = 0
        for x in nums:
            ans = (ans + (x * x % MOD) * (s + x)) % MOD
            s = (2 * s + x) % MOD
        return ans

class Solution {
public:
    int sumOfPower(std::vector<int>& nums) {
        long long MOD = 1e9 + 7;
        std::sort(nums.begin(), nums.end());
        long long ans = 0, s = 0;
        for (long long x : nums) {
            long long term = (x * x) % MOD;
            ans = (ans + term * ((s + x) % MOD)) % MOD;
            s = (2 * s + x) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int sumOfPower(int[] nums) {
        long MOD = 1_000_000_007L;
        Arrays.sort(nums);
        long ans = 0, s = 0;
        for (int v : nums) {
            long x = v;
            long term = (x * x) % MOD;
            ans = (ans + term * ((s + x) % MOD)) % MOD;
            s = (2 * s + x) % MOD;
        }
        return (int)ans;
    }
}

var sumOfPower = function(nums) {
    const MOD = 1000000007n;
    nums.sort((a, b) => a - b);
    let ans = 0n, s = 0n;
    for (const v of nums) {
        const x = BigInt(v);
        const term = (x * x) % MOD;
        ans = (ans + term * ((s + x) % MOD)) % MOD;
        s = (2n * s + x) % MOD;
    }
    return Number(ans);
};
